import React, { forwardRef } from 'react';
import { Box } from '@fiverr-private/theme';
import { LinkCardProps } from '../types';
import { border } from '../shared';

const LinkCard = forwardRef<HTMLElement, LinkCardProps>(
  (
    {
      children,
      href,
      borderRadius = 'sm',
      color = { default: 'linkPrimary' },
      dataTrackTag = 'link_card',
      outlineColor = {
        focusVisible: 'grey_1200',
      },
      outlineOffset = {
        focusVisible: 'sm',
      },
      outlineWidth = {
        focusVisible: 'md',
      },
      outlineStyle = { focusVisible: 'solid' },
      ...restProps
    }: LinkCardProps,
    ref
  ) => (
    <Box
      as="a"
      ref={ref}
      href={href}
      boxShadow={{ hover: 'z2' }}
      borderRadius={borderRadius}
      decoration="none"
      color={color}
      dataTrackTag={dataTrackTag}
      outlineColor={outlineColor}
      outlineOffset={outlineOffset}
      outlineWidth={outlineWidth}
      outlineStyle={outlineStyle}
      {...border}
      {...restProps}
    >
      {children}
    </Box>
  )
);

LinkCard.displayName = 'LinkCard';

export default LinkCard;
